-- Full PostgreSQL schema and sample seed data generated from prisma/schema.prisma and prisma/seed.ts
BEGIN;

-- Enums
CREATE TYPE "UserRole" AS ENUM ('ADMIN', 'TEACHER', 'PARENT', 'STUDENT');
CREATE TYPE "QuestionType" AS ENUM ('TRAC_NGHIEM', 'TU_LUAN');
CREATE TYPE "Difficulty" AS ENUM ('NHAN_BIET', 'THONG_HIEU', 'VAN_DUNG');
CREATE TYPE "ExamCategory" AS ENUM ('CO_BAN', 'NANG_CAO');
CREATE TYPE "ExamFormat" AS ENUM ('TRAC_NGHIEM', 'TU_LUAN', 'KET_HOP');
CREATE TYPE "ScanStatus" AS ENUM ('PENDING', 'PROCESSED', 'NEEDS_REVIEW');
CREATE TYPE "ExamPeriod" AS ENUM ('GIUA_KI_1', 'CUOI_KI_1', 'GIUA_KI_2', 'CUOI_KI_2', 'CA_NAM');
CREATE TYPE "ExamScopeType" AS ENUM ('LESSON', 'PERIOD');
CREATE TYPE "EnrollmentStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED');
CREATE TYPE "MaterialType" AS ENUM ('SLIDE_PPT', 'VIDEO', 'DOCUMENT');
CREATE TYPE "MaterialAccessType" AS ENUM ('FREE', 'PAID');
CREATE TYPE "InvitationTargetRole" AS ENUM ('PARENT', 'STUDENT');

-- Tables
CREATE TABLE "User" (
  "id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "passwordHash" TEXT NOT NULL,
  "role" "UserRole" NOT NULL,
  "phone" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "User_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Student" (
  "id" TEXT NOT NULL,
  "fullName" TEXT NOT NULL,
  "dob" TIMESTAMP(3),
  "gradeId" TEXT NOT NULL,
  "createdByTeacherId" TEXT NOT NULL,
  "userId" TEXT,
  CONSTRAINT "Student_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "ParentStudent" (
  "id" TEXT NOT NULL,
  "parentUserId" TEXT NOT NULL,
  "studentId" TEXT NOT NULL,
  "relationship" TEXT,
  "isOwner" BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT "ParentStudent_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Classroom" (
  "id" TEXT NOT NULL,
  "teacherId" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "subjectId" TEXT NOT NULL,
  "gradeId" TEXT NOT NULL,
  "description" TEXT,
  CONSTRAINT "Classroom_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "ClassroomStudent" (
  "id" TEXT NOT NULL,
  "classroomId" TEXT NOT NULL,
  "studentId" TEXT NOT NULL,
  "joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "ClassroomStudent_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Subject" (
  "id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  CONSTRAINT "Subject_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Grade" (
  "id" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "level" INTEGER NOT NULL,
  CONSTRAINT "Grade_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Topic" (
  "id" TEXT NOT NULL,
  "subjectId" TEXT NOT NULL,
  "gradeId" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  CONSTRAINT "Topic_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Lesson" (
  "id" TEXT NOT NULL,
  "subjectId" TEXT NOT NULL,
  "gradeId" TEXT NOT NULL,
  "topicId" TEXT,
  "name" TEXT NOT NULL,
  "orderNo" INTEGER NOT NULL,
  "description" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "Lesson_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Question" (
  "id" TEXT NOT NULL,
  "topicId" TEXT,
  "gradeId" TEXT NOT NULL,
  "subjectId" TEXT NOT NULL,
  "type" "QuestionType" NOT NULL,
  "difficulty" "Difficulty" NOT NULL,
  "examCategory" "ExamCategory" NOT NULL,
  "content" TEXT NOT NULL,
  "answerText" TEXT,
  "score" DECIMAL(65,30) NOT NULL DEFAULT 1.0,
  "createdById" TEXT NOT NULL,
  "lessonId" TEXT,
  CONSTRAINT "Question_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "QuestionExamPeriod" (
  "id" TEXT NOT NULL,
  "questionId" TEXT NOT NULL,
  "period" "ExamPeriod" NOT NULL,
  CONSTRAINT "QuestionExamPeriod_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "QuestionOption" (
  "id" TEXT NOT NULL,
  "questionId" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "content" TEXT NOT NULL,
  "isCorrect" BOOLEAN NOT NULL DEFAULT false,
  CONSTRAINT "QuestionOption_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "Exam" (
  "id" TEXT NOT NULL,
  "teacherId" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "subjectId" TEXT NOT NULL,
  "gradeId" TEXT NOT NULL,
  "examCategory" "ExamCategory" NOT NULL,
  "examFormat" "ExamFormat" NOT NULL,
  "totalScore" DECIMAL(65,30) NOT NULL,
  "durationMinutes" INTEGER NOT NULL,
  "scopeType" "ExamScopeType" NOT NULL DEFAULT PERIOD,
  "examPeriod" "ExamPeriod",
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
