);

CREATE TABLE "ExamLesson" (
  "id" TEXT NOT NULL,
  "examId" TEXT NOT NULL,
  "lessonId" TEXT NOT NULL,
  CONSTRAINT "ExamLesson_pkey" PRIMARY KEY ("id")
);

