);

CREATE TABLE "ExamResult" (
  "id" TEXT NOT NULL,
  "examCodeId" TEXT NOT NULL,
  "studentId" TEXT,
  "totalScore" DECIMAL(65,30),
  "correctCount" INTEGER,
  "wrongCount" INTEGER,
  "blankCount" INTEGER,
