CREATE TABLE "Schedule" (
  "id" TEXT NOT NULL,
  "classroomId" TEXT NOT NULL,
  "dayOfWeek" INTEGER,
  "specificDate" TIMESTAMP(3),
  "startTime" TEXT NOT NULL,
  "endTime" TEXT NOT NULL,
  "location" TEXT,
  "note" TEXT,
  CONSTRAINT "Schedule_pkey" PRIMARY KEY ("id")
