CREATE TABLE "EnrollmentRequest" (
  "id" TEXT NOT NULL,
  "parentUserId" TEXT NOT NULL,
  "studentId" TEXT NOT NULL,
  "classroomId" TEXT NOT NULL,
  "status" "EnrollmentStatus" NOT NULL DEFAULT PENDING,
